#include <zephyr/ztest.h>
#include <zephyr/dfu/img_util.h>
#include <zephyr/dfu/mcuboot.h> /* For mcuboot_img_header structure */
#include <string.h>

/* Define a minimal, valid MCUboot image header for testing */
#define TEST_IMAGE_MAGIC        0x96f3b83c
#define TEST_IMAGE_HEADER_SIZE  sizeof(struct mcuboot_img_header)
#define TEST_IMAGE_PAYLOAD_SIZE 64
#define TEST_IMAGE_TOTAL_SIZE   (TEST_IMAGE_HEADER_SIZE + TEST_IMAGE_PAYLOAD_SIZE)
#define TEST_IMAGE_VERSION_MAJOR 1
#define TEST_IMAGE_VERSION_MINOR 0
#define TEST_IMAGE_VERSION_PATCH 0
#define TEST_IMAGE_VERSION_BUILD 0

/* Placeholder for a valid image header and some data */
static struct mcuboot_img_header test_img_header = {
    .ih_magic = TEST_IMAGE_MAGIC,
    .ih_tlv_size = 0,
    .ih_hdr_size = TEST_IMAGE_HEADER_SIZE,
    .ih_img_size = TEST_IMAGE_PAYLOAD_SIZE,
    .ih_flags = 0,
    .ih_ver = {
        .iv_major = TEST_IMAGE_VERSION_MAJOR,
        .iv_minor = TEST_IMAGE_VERSION_MINOR,
        .iv_patch = TEST_IMAGE_VERSION_PATCH,
        .iv_build = TEST_IMAGE_VERSION_BUILD,
    },
    ._pad1 = 0,
};

/* Combine header and payload into a single buffer */
static uint8_t dummy_image_data[TEST_IMAGE_TOTAL_SIZE];

/*
 * The img_util library might provide a function that returns a pointer
 * to the parsed header or fills a generic info struct.
 * For this fix, we assume a function `img_util_get_header_info` exists
 * that takes the image buffer and its size, and returns a pointer to
 * a `const struct mcuboot_img_header` if successful, or NULL on failure.
 * This is a common pattern for image parsing utilities.
 */
extern const struct mcuboot_img_header *img_util_get_header_info(
	const uint8_t *img_data, size_t img_size);

static void img_util_test_collecting(void)
{
    const struct mcuboot_img_header *collected_hdr;

    /* Initialize dummy_image_data with the header and some dummy payload */
    memcpy(dummy_image_data, &test_img_header, TEST_IMAGE_HEADER_SIZE);
    memset(dummy_image_data + TEST_IMAGE_HEADER_SIZE, 0xAA, TEST_IMAGE_PAYLOAD_SIZE);

    /* Call the hypothetical API to collect image header information */
    collected_hdr = img_util_get_header_info(dummy_image_data, TEST_IMAGE_TOTAL_SIZE);

    zassert_not_null(collected_hdr, "img_util_get_header_info returned NULL");

    /* Verify collected info against expected values */
    zassert_equal(collected_hdr->ih_magic, TEST_IMAGE_MAGIC,
                  "Collected magic mismatch: 0x%x != 0x%x", collected_hdr->ih_magic, TEST_IMAGE_MAGIC);
    zassert_equal(collected_hdr->ih_hdr_size, TEST_IMAGE_HEADER_SIZE,
                  "Collected header size mismatch: %u != %u", collected_hdr->ih_hdr_size, TEST_IMAGE_HEADER_SIZE);
    zassert_equal(collected_hdr->ih_img_size, TEST_IMAGE_PAYLOAD_SIZE,
                  "Collected image size mismatch: %u != %u", collected_hdr->ih_img_size, TEST_IMAGE_PAYLOAD_SIZE);
    zassert_equal(collected_hdr->ih_ver.iv_major, TEST_IMAGE_VERSION_MAJOR,
                  "Collected major version mismatch: %u != %u", collected_hdr->ih_ver.iv_major, TEST_IMAGE_VERSION_MAJOR);
    zassert_equal(collected_hdr->ih_ver.iv_minor, TEST_IMAGE_VERSION_MINOR,
                  "Collected minor version mismatch: %u != %u", collected_hdr->ih_ver.iv_minor, TEST_IMAGE_VERSION_MINOR);
    zassert_equal(collected_hdr->ih_ver.iv_patch, TEST_IMAGE_VERSION_PATCH,
                  "Collected patch version mismatch: %u != %u", collected_hdr->ih_ver.iv_patch, TEST_IMAGE_VERSION_PATCH);
    zassert_equal(collected_hdr->ih_ver.iv_build, TEST_IMAGE_VERSION_BUILD,
                  "Collected build version mismatch: %u != %u", collected_hdr->ih_ver.iv_build, TEST_IMAGE_VERSION_BUILD);
}

void test_main(void)
{
    ztest_suite(img_util_tests,
                ztest_unit_test(img_util_test_collecting)
                );
    ztest_run_suite(img_util_tests);
}
